import fs from 'node:fs/promises';
import { chromium } from 'playwright';
const BASE='https://www.statesideqm.com',THEME='158561894555',sleep=ms=>new Promise(r=>setTimeout(r,ms));
const roots=['accessories-gifts-collectibles','airsoft-milsim','apparel','armed-forces-gear','art','body-armor-ballistic-protection','literature','child-safety-shop','dive-scuba','firearm-accessories','first-aid-medical-ifak','flags-patriotic-decor','flashlights-lighting','footwear-gloves-eyewear','k9-dog-gear','knives-axes-cutlery','morale-patches-tactical-id','outdoor-preparedness-gear','patriotic-american-heritage','safety-rescue-climbing','sta-brite-insignia','tactical-gear','thin-line','uniforms','watches','zippos-lighters-torches','stateside-quartermaster-logo-merch','army-national-guard-series','air-national-guard-series','products-built-for-the-line-u-s-army','products-built-for-the-line-u-s-navy','products-built-for-the-line-u-s-air-force','products-built-for-the-line-u-s-marine-corps','products-built-for-the-line-u-s-coast-guard','products-built-for-the-line-u-s-space-force','rotc-series','jrotc-series','military-schools-academies','law-enforcement-corrections','firefighting-ems-search-rescue'];
const browser=await chromium.launch({headless:true});const context=await browser.newContext({viewport:{width:1440,height:1000}});const page=await context.newPage();
const key=s=>String(s||'').toLowerCase().replace(/[’']/g,'').replace(/&/g,' ').replace(/\band\b/g,' ').replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim();
async function gotoRoot(handle){let last='';for(let a=0;a<3;a++){try{await page.goto(`${BASE}/collections/${handle}?preview_theme_id=${THEME}&sq_semantic_audit=${Date.now()}`,{waitUntil:'domcontentloaded',timeout:90000});await page.waitForFunction(()=>document.querySelector('#MainContent')?.dataset.sqRefineV3Ready==='true',null,{timeout:45000});await page.waitForSelector('#MainContent .sq-refine-v3-sidebar',{state:'visible',timeout:15000});await sleep(700);return}catch(e){last=String(e);await sleep(1500*(a+1))}}throw new Error(last)}
const results=[],failures=[],warnings=[];
for(const handle of roots){try{await gotoRoot(handle);const d=await page.evaluate(()=>{const side=document.querySelector('#MainContent .sq-refine-v3-sidebar');return{normalized:side?.dataset.sqRefineV3TaxonomyNormalized||'',groups:[...side.querySelectorAll('details.sq-refine-v3-group')].map(x=>({title:(x.querySelector(':scope>summary')?.textContent||'').replace(/\s+/g,' ').trim(),items:[...x.querySelectorAll('.sq-refine-v3-choice')].map(c=>{const i=c.querySelector('input');return{label:(c.querySelector('span')?.textContent||'').replace(/\s+/g,' ').trim(),kind:i?.dataset.kind||'',target:i?.dataset.target||''}})}))}});const tax=d.groups.filter(g=>/^Shop by (Category|Subcategory|Type|Branch)$/i.test(g.title));const seen=new Map(),dupes=[];for(const g of tax)for(const i of g.items){const k=key(i.label);if(!k)continue;if(seen.has(k))dupes.push({label:i.label,first:seen.get(k),second:g.title});else seen.set(k,g.title)}const badTargets=[];for(const g of tax)for(const i of g.items.filter(x=>x.kind==='structural')){try{const u=new URL(i.target,BASE);if(u.searchParams.get('sq_root')!==handle)badTargets.push({group:g.title,label:i.label,target:i.target})}catch{badTargets.push({group:g.title,label:i.label,target:i.target})}}const empty=tax.filter(g=>g.items.length===0).map(g=>g.title);const type=tax.find(g=>/^Shop by Type$/i.test(g.title));const r={handle,normalized:d.normalized,groups:tax.map(g=>({title:g.title,count:g.items.length})),duplicates:dupes,badTargets,empty};results.push(r);if(d.normalized!=='true')failures.push({handle,reason:'taxonomy normalizer missing'});if(dupes.length)failures.push({handle,reason:'duplicate hierarchy labels',dupes});if(badTargets.length)failures.push({handle,reason:'bad structural sq_root',badTargets});if(empty.length)failures.push({handle,reason:'empty taxonomy group',empty});if(type&&type.items.length>80)warnings.push({handle,reason:'oversized Type group',count:type.items.length});console.log('SEMANTIC_ROOT '+JSON.stringify(r))}catch(e){failures.push({handle,reason:'load failure',error:String(e)});console.log('SEMANTIC_ROOT '+JSON.stringify({handle,error:String(e)}))}}
await page.goto(`${BASE}/collections/state-guard-series?preview_theme_id=${THEME}`,{waitUntil:'domcontentloaded',timeout:90000});await sleep(1800);const sg=await page.evaluate(()=>({ready:document.querySelector('#MainContent')?.dataset.sqRefineV3Ready||'',side:!!document.querySelector('#MainContent .sq-refine-v3-sidebar'),normalized:document.querySelector('#MainContent .sq-refine-v3-sidebar')?.dataset.sqRefineV3TaxonomyNormalized||'',child:document.documentElement.dataset.sqRefineV3ChildIsolation||''}));if(sg.ready||sg.side||sg.normalized||sg.child)failures.push({handle:'state-guard-series',reason:'State Guard touched by V3',sg});
await fs.mkdir('taxonomy-v3',{recursive:true});await fs.writeFile('taxonomy-v3/semantic-audit.json',JSON.stringify({results,sg,failures,warnings},null,2));console.log('SEMANTIC_SUMMARY '+JSON.stringify({roots:roots.length,stateGuard:sg,failures,warnings}));await browser.close();if(failures.length)process.exit(1);
